import AppKit
import ApplicationServices
import Foundation

/// Decides whether a copy should be remembered. Password managers mark secrets with the
/// nspasteboard.org types; those (and apps on the ignore list) are never stored.
public enum PasteboardFilter {
    public static let skippedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword", "de.petermaurer.TransientPasteboardType",
    ]

    public static let defaultIgnoredApps: Set<String> = [
        "com.1password.1password", "com.agilebits.onepassword7", "com.bitwarden.desktop",
        "com.apple.keychainaccess", "com.apple.Passwords", "com.lastpass.LastPass", "com.dashlane.dashlanephonefinal",
    ]

    public static func shouldStore(types: [String], sourceApp: String?, ignoredApps: Set<String> = defaultIgnoredApps) -> Bool {
        if types.contains(where: skippedTypes.contains) { return false }
        if let sourceApp, ignoredApps.contains(sourceApp) { return false }
        return !types.isEmpty
    }
}

/// What was copied, read off the pasteboard.
public enum PasteboardContent: Sendable {
    case text(String)
    case url(String)
    case files([String])
    case image(png: Data, width: Int, height: Int)

    public static func read(_ pasteboard: NSPasteboard) -> PasteboardContent? {
        if let urls = pasteboard.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL], !urls.isEmpty {
            return .files(urls.map(\.path))
        }
        if let string = pasteboard.string(forType: .string), !string.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            if let url = URL(string: string.trimmingCharacters(in: .whitespacesAndNewlines)), let scheme = url.scheme, ["http", "https"].contains(scheme), !string.contains(" ") {
                return .url(string.trimmingCharacters(in: .whitespacesAndNewlines))
            }
            return .text(string)
        }
        if let image = NSImage(pasteboard: pasteboard), let tiff = image.tiffRepresentation,
            let bitmap = NSBitmapImageRep(data: tiff), let png = bitmap.representation(using: .png, properties: [:]) {
            return .image(png: png, width: bitmap.pixelsWide, height: bitmap.pixelsHigh)
        }
        return nil
    }
}

/// Polls `NSPasteboard.general.changeCount` every 250 ms (macOS has no copy notification).
@MainActor
public final class PasteboardMonitor {
    public typealias Sink = @Sendable (PasteboardContent, String?) async -> Void

    private var timer: Timer?
    private var lastChange = NSPasteboard.general.changeCount
    private var ownWriteChange: Int?
    private let sink: Sink
    public var ignoredApps = PasteboardFilter.defaultIgnoredApps

    public init(sink: @escaping Sink) {
        self.sink = sink
    }

    public func start() {
        guard timer == nil else { return }
        lastChange = NSPasteboard.general.changeCount
        let timer = Timer(timeInterval: 0.25, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { self?.poll() }
        }
        timer.tolerance = 0.1
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    public func stop() {
        timer?.invalidate()
        timer = nil
    }

    /// Call right after Lizard writes to the pasteboard so that write isn't recorded again.
    public func markOwnWrite() {
        ownWriteChange = NSPasteboard.general.changeCount
    }

    private func poll() {
        let pasteboard = NSPasteboard.general
        let change = pasteboard.changeCount
        guard change != lastChange else { return }
        lastChange = change
        if change == ownWriteChange { return }
        let types = pasteboard.types?.map(\.rawValue) ?? []
        let source = NSWorkspace.shared.frontmostApplication?.bundleIdentifier
        guard PasteboardFilter.shouldStore(types: types, sourceApp: source, ignoredApps: ignoredApps),
            let content = PasteboardContent.read(pasteboard)
        else { return }
        let sink = sink
        Task { await sink(content, source) }
    }
}

/// Puts an item back on the pasteboard and pastes it into the app that was in front.
@MainActor
public enum AutoPaste {
    public static var isTrusted: Bool { AXIsProcessTrusted() }

    public static func requestTrust() {
        _ = AXIsProcessTrustedWithOptions(["AXTrustedCheckOptionPrompt": true] as CFDictionary)
    }

    public static func copy(_ item: ClipItem) {
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        switch item.kind {
        case .image:
            if let path = item.imagePath, let image = NSImage(contentsOfFile: path) { pasteboard.writeObjects([image]) }
        case .file:
            let urls = item.text.split(separator: "\n").map { URL(filePath: String($0)) as NSURL }
            pasteboard.writeObjects(urls)
        default:
            pasteboard.setString(item.text, forType: .string)
        }
    }

    public static func copy(text: String) {
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(text, forType: .string)
    }

    /// Activates `app`, then sends ⌘V. Needs Accessibility; returns false without it.
    @discardableResult
    public static func paste(into app: NSRunningApplication?) -> Bool {
        guard isTrusted else { return false }
        app?.activate()
        Task { @MainActor in
            try? await Task.sleep(for: .milliseconds(90))
            let source = CGEventSource(stateID: .combinedSessionState)
            let down = CGEvent(keyboardEventSource: source, virtualKey: 9, keyDown: true)
            let up = CGEvent(keyboardEventSource: source, virtualKey: 9, keyDown: false)
            down?.flags = .maskCommand
            up?.flags = .maskCommand
            down?.post(tap: .cghidEventTap)
            up?.post(tap: .cghidEventTap)
        }
        return true
    }
}
